Script:
Write-Host "Welcome to Azure Script step"

if (!(Get-Module -ListAvailable -Name Az.Accounts)) {
  Install-Module -Name Az.Accounts -Repository PSGallery -AllowClobber -Force -Scope CurrentUser
} 

Import-Module Az.Accounts

Write-Host "Logging in to Azure Account"

$aza = $Jaws.Parameters["STEP.AzureAccount"].ValueAsMap()

$AzTenantId = $aza["TenantID"].Value
$AzSubscriptionId = $aza["SubscriptionID"].Value
$AzApplicationId = $aza["ApplicationID"].Value
$AzApplicationPassword = $aza["ApplicationPassword"].Value

if ([string]::IsNullOrWhiteSpace($AzTenantId)) {
  throw "Required parameter STEP.AzureAccount.TenantID not specified"
}
if ([string]::IsNullOrWhiteSpace($AzApplicationId)) {
  throw "Required parameter STEP.AzureAccount.ApplicationID not specified"
}
if ([string]::IsNullOrWhiteSpace($AzApplicationPassword)) {
  throw "Required parameter STEP.AzureAccount.ApplicationPassword not specified"
}

Set-JawsAzLogin -TenantId $AzTenantId -ApplicationId $AzApplicationId -Password $AzApplicationPassword -SubscriptionId $AzSubscriptionId

#SCRIPTREFERENCE(STEP.ScriptBody)

Write-Host "Azure Script step complete"

Remove-JawsAzLogin
Write-Host "Logged off from Azure"
